steps = [
    step("什么都不配,装了 spring-boot-starter-actuator 之后能通过 HTTP 访问什么。GET /actuator 返回 200,链接只有 health、health-path 和 self;GET /actuator/health 是 200,内容只有 groups(liveness、readiness)和 status: UP,不带组件明细。/actuator/info、/actuator/env、/actuator/metrics、/actuator/beans、/actuator/heapdump 全是 404。也就是说默认只暴露 health,其余端点即使存在也访问不到。", t=tl(S(1)), mark=lidx(S(1), 'GET /actuator/env', 'GET /actuator/heapdump'), done=lidx(S(1), 'GET /actuator →', 'GET /actuator/health'), b=bars([['默认 /actuator 里的端点链接数(含 self、health-path)', 3, '3'], ['/actuator/health 的状态码(200)', 200, '200'], ['/actuator/env 的状态码', 404, '404']], 404, done=[0, 1], mark=[2]), kv=KV([['默认暴露', '只有 health'], ['health 内容', '只有 status 和 groups,没有组件明细'], ['其他端点', '404'], ['打开', 'management.endpoints.web.exposure.include']], ['默认暴露'])),
    step("management.endpoints.web.exposure.include=* 之后,/actuator 有 19 个链接(含 self),端点是 beans、conditions、configprops、env、health、info、loggers、mappings、metrics、sbom、scheduledtasks、threaddump 等(其中带 -prefix、-toMatch、-name 之类后缀的是同一个端点的带参数形式)。这些端点都没有认证:env 8 KB、beans 99 KB、mappings 19 KB、threaddump 60 KB、configprops 13 KB、loggers 31 KB、conditions 65 KB,都能直接 GET 到。两个特别的:heapdump 在 include=* 下 GET 是 404,/actuator 里没有它;额外写 management.endpoint.heapdump.access=unrestricted 之后它出现在列表里,GET /actuator/heapdump 返回 200、application/octet-stream、32.2 MB,请求里没有任何认证信息。shutdown 同样:include=* 下 POST /actuator/shutdown 是 404;设了 management.endpoint.shutdown.access=unrestricted 后返回 200「Shutting down, bye...」,3 秒后 java 进程已经退出,退出码 0。反过来,management.endpoint.env.access=none 会把 env 从列表里拿掉,GET /actuator/env 变成 404。暴露(exposure)与访问权限(access)是两把锁,heapdump、shutdown 默认都没有开 access。", t=tl(S(2)), mark=lidx(S(2), 'GET /actuator/heapdump → 200', 'POST /actuator/shutdown → 200', '/actuator 里有 env:False'), done=lidx(S(2), '共 19 个链接', 'GET /actuator/env → 200', 'GET /actuator/threaddump', '/actuator 里有 heapdump:True'), b=bars([['include=* 之后 /actuator 的链接数', 19, '19'], ['heapdump 响应大小(MB)', 32, '32.2'], ['env 响应大小(KB)', 8, '8'], ['beans 响应大小(KB)', 99, '99']], 99, mark=[1], done=[0, 2, 3]), kv=KV([['include=*', '19 个链接,全部没有认证'], ['heapdump', '还要 access=unrestricted;打开后 32.2 MB,没有认证'], ['shutdown', '还要 access=unrestricted;打开后 POST 就退出进程'], ['access=none', '该端点从列表里消失,返回 404']], ['heapdump'])),
    step("/actuator/env 里的值。系统属性里放了 app.name=demo、app.password=p@ssw0rd、app.token=tok-123、app.url=http://example.com。默认情况(management.endpoint.env.show-values 不设):四个属性的值全是 '******',包括 app.name 和 app.url 这种并不敏感的——默认是整体脱敏,不是按名字猜。management.endpoint.env.show-values=ALWAYS:四个值全部明文,app.password 是 p@ssw0rd,app.token 是 tok-123。show-values=WHEN_AUTHORIZED 但没有装 Spring Security:还是 '******'。想要看明文要显式打开 ALWAYS,或者装了 Spring Security 之后用 WHEN_AUTHORIZED(后一种没有在本篇验证)。", t=tl(S(3)), mark=lidx(S(3), 'show-values=ALWAYS'), done=lidx(S(3), '默认(management.endpoint.env.show-values 不设)', 'WHEN_AUTHORIZED'), b=bars([['默认下被脱敏的属性个数(共 4 个)', 4, '4'], ['show-values=ALWAYS 下被脱敏的个数', 0, '0'], ['WHEN_AUTHORIZED 无 Security 下被脱敏的个数', 4, '4']], 4, done=[0, 2], mark=[1]), kv=KV([['默认', '所有值都是 ******,不管名字敏不敏感'], ['ALWAYS', '全部明文,包括 password、token'], ['WHEN_AUTHORIZED', '没有 Security 时仍然脱敏'], ['结论', '开 ALWAYS 前先确认端点不对外']], ['ALWAYS'])),
    step("单独的管理端口与基础路径。management.server.port 设成另一个端口之后:业务端口上 GET /actuator/health 是 404,管理端口上 GET /fast 也是 404,两边互相看不到对方。有一个时间差:业务端口可连接之后,管理端口又过了 261 ms 才连得上(这段时间连接被拒绝了 11 次),连上之后第一次响应是 503、内容 status: DOWN,2 秒后同一个请求是 200、status: UP——管理端口比业务端口晚开,而且刚开的一瞬间 health 还不是 UP,按业务端口可连接来判断「已经起来了」或者拿管理端口做探针时要留意。management.endpoints.web.base-path=/ops 之后 /actuator/health 是 404,/ops/health 是 200。", t=tl(S(4)), mark=lidx(S(4), 'management.server.port='), done=lidx(S(4), 'base-path=/ops'), b=bars([['管理端口比业务端口晚连上的时间(ms)', 261, '261'], ['此前被拒绝的连接次数', 11, '11'], ['第一次响应的状态码 503 对应的 2 秒后状态码 200', 200, '503 → 200']], 261, mark=[0, 1], done=[2]), kv=KV([['两个端口', '互相看不到对方的路径'], ['管理端口', '比业务端口晚开,刚开时 health 返回 503 DOWN'], ['base-path', '/actuator 换成 /ops 后旧路径 404'], ['探针', '要考虑管理端口晚就绪']], ['管理端口'])),
    step("装了 actuator 的启动和内存开销(每组 7 次,同一份业务代码)。没有 actuator:启动到端口可连接中位 817 ms(范围 815 到 917),启动后常驻内存中位 168 MB;有 actuator(默认配置):中位 1082 ms(范围 972 到 1203),常驻内存 184 MB。启动慢了约 265 ms、内存多了约 16 MB(算出来的差)。注意本次测试时机器上还有别的程序在跑,所以这个差值只能当量级看。我原本还想比较装 actuator 之后每个请求的吞吐开销,但调试中几轮压测都被机器负载搅得抖动很大(同一组的几轮之间差到几倍),没有得到可信的结果,这部分没有放进文章。", t=tl(S(5)), mark=lidx(S(5), '有 actuator(默认)'), done=lidx(S(5), '没有 actuator'), b=bars([['没有 actuator 启动到端口可连接(ms)', 817, '817'], ['有 actuator 启动到端口可连接(ms)', 1082, '1082'], ['没有 actuator 常驻内存(MB)', 168, '168'], ['有 actuator 常驻内存(MB)', 184, '184']], 1082, mark=[1, 3], done=[0, 2]), kv=KV([['启动', '817 ms → 1082 ms(量级参考)'], ['内存', '168 MB → 184 MB'], ['请求吞吐', '没有得到可信的对比,不下结论'], ['可信度', '测试时机器上有别的负载']], ['请求吞吐'])),
]
